def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0 if hp > 3 else 42.0
        return float(max(0.0, min(budget, base)))

    opp_bids = []
    bob_bid = None
    cindy_bid = None
    dangerous_count = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid'))
            opp_bids.append(bid)
        req = opp.get('water_requirement', WATER_REQ)
        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        if oid == 'Bob' and bid is not None:
            bob_bid = bid
        if oid == 'Cindy' and bid is not None:
            cindy_bid = bid
        if req >= WATER_REQ and obudget > 0 and ohp > 0:
            dangerous_count += 1

    high_supply = supply >= 22
    low_supply = supply <= 17
    very_low_supply = supply <= 16

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if low_supply:
        urgency += 1
    if very_low_supply:
        urgency += 1
    if day >= 8:
        urgency += 1

    target = 0.0

    if urgency >= 5:
        if cindy_bid is not None and low_supply:
            target = max(95.0, cindy_bid + 3.0)
        elif bob_bid is not None:
            target = max(72.0, bob_bid + 2.5)
        else:
            target = 84.0
    elif urgency >= 3:
        if low_supply:
            if bob_bid is not None:
                target = max(58.0, bob_bid + 2.0)
            else:
                target = 61.0
            if cindy_bid is not None and cindy_bid < 90:
                target = max(target, cindy_bid + 2.0)
        else:
            if bob_bid is not None:
                target = max(50.0, bob_bid + 1.5)
            else:
                target = 52.0
    else:
        if high_supply:
            target = 24.0
            if bob_bid is not None:
                target = min(38.0, max(24.0, bob_bid - 10.0))
        elif low_supply:
            if cindy_bid is not None and cindy_bid > 100:
                target = 34.0
            elif bob_bid is not None:
                target = max(49.0, bob_bid + 1.2)
            else:
                target = 48.0
        else:
            if bob_bid is not None:
                target = max(46.0, bob_bid + 1.0)
            else:
                target = 47.0

    if cindy_bid is not None and cindy_bid >= 120 and urgency <= 3 and not very_low_supply:
        target = min(target, 44.0 if not low_supply else 50.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = max(0.0, (10 - day) * 18.0)
    affordable = max(0.0, budget - reserve_floor)

    if urgency >= 4:
        bid = min(budget, max(target, affordable * 0.6 if affordable > 0 else target))
    else:
        bid = min(budget, target)
        if affordable > 0:
            bid = min(bid, max(affordable, 0.0) + 8.0)

    if hp <= 1 or no_water_days >= 2:
        bid = max(bid, min(budget, 96.0))

    if high_supply and urgency == 0:
        bid = min(bid, 28.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.75
    elif my_hp >= 8:
        base_bid = DAILY_SALARY * 0.4

    if current_day >= EPISODE_DAYS - 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    if current_supply < WATER_REQ + 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.6)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > DAILY_SALARY * 0.8:
            if my_hp <= 4 or current_supply < WATER_REQ + 5:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.6)
        elif highest_prev_bid > DAILY_SALARY * 0.4:
            base_bid = max(base_bid, highest_prev_bid + 2)

    final_bid = min(my_budget, base_bid)

    if final_bid == 0 and my_budget > 0:
        return min(my_budget, 1)
    elif final_bid == 0 and my_budget == 0:
        return 0

    return final_bid

